/bin/bash -lc "node --input-type=module <<'JS'
import { mkdir, writeFile } from 'node:fs/promises';
await mkdir('public/fonts', {recursive:true});
const css=await (await fetch('https://fonts.googleapis.com/css2?family=Golos+Text:wght@400..800&display=swap',{headers:{'User-Agent':'Mozilla/5.0'}})).text();
const urls=[...new Set([...css.matchAll(/url\\((["'^)]+)'"\\)/g)].map(m=>m[1]))];
let localCss=css;
for(let i=0;i<urls.length;i++){const ext=urls[i].endsWith('.woff2')?'woff2':'ttf';const path="'`/fonts/golos-${i}.${ext}`;await writeFile(`public${path}`,Buffer.from(await (await fetch(urls[i])).arrayBuffer()));localCss=localCss.replaceAll(urls[i],path);}
await writeFile('"'public/fonts/golos.css',localCss);
console.log('Font saved locally',urls.length);
JS"

